 *   } catch (err) {
 *     if (isTransportFailure(err)) {
 *       this.cache.delete(peerId);   // don't hand the broken stub to the next caller
 *       handle?.close().catch(() => {});
 *     }
 *     throw err;
 *   }
 * }
